import AppKit

// Menu bar glyphs, variant A (approved mock 2026-10-30, menubar-mock3): the official logo shapes at their natural
// weight (no added outline), fitted to the pixel grid by placement only: each shape was rendered at every 1/8 px
// offset inside a (w+1) x (h+1) px cell and the crispest placement kept, then stored as alpha masks at 1x and 2x.
// Heights: 15 px (Gemini star and Antigravity 14 px). Drawn as template ink, so macOS tints them per menu bar.
enum MenuBarGlyphs {
    struct Glyph {
        let cellW: Int, cellH: Int  // cell in points (= 1x pixels); the 2x mask is twice as large
        let advance: Int            // width taken in the strip before the bar gap (shape width, +1 when shifted right)
        let png1x: String, png2x: String  // base64 PNG, black ink in the alpha channel
    }

    // OpenAI Blossom, official SVG path (assets/official-originals/openai-blossom-black.svg); 15x15 px shape, placement offset 0/8, 0/8 px
    static let codex = Glyph(cellW: 16, cellH: 16, advance: 15,
        png1x: "",
        png2x: "")
    // Claude spark, official SVG path (claude-symbol.svg); 15x15 px shape, placement offset 1/8, 0/8 px
    static let claude = Glyph(cellW: 16, cellH: 16, advance: 16,
        png1x: "",
        png2x: "")
    // Grok mark, mask from the official PNG; 16x15 px shape, placement offset 0/8, 5/8 px
    static let grok = Glyph(cellW: 17, cellH: 16, advance: 16,
        png1x: "",
        png2x: "")
    // Gemini star, mask from the official PNG; 14x14 px shape, placement offset 4/8, 4/8 px
    static let gemini = Glyph(cellW: 15, cellH: 15, advance: 15,
        png1x: "",
        png2x: "")
    // Antigravity mark, mask from the official PNG; 15x14 px shape, placement offset 0/8, 2/8 px
    static let antigravity = Glyph(cellW: 16, cellH: 15, advance: 15,
        png1x: "",
        png2x: "")

    static func named(_ key: String) -> Glyph? {
        switch key {
        case "codex": return codex
        case "claude": return claude
        case "grok": return grok
        case "gemini": return gemini
        case "antigravity": return antigravity
        default: return nil
        }
    }

    // the glyph as an image with a 1x and a 2x bitmap, size in points = the 1x cell; cached
    private static var cache: [String: NSImage] = [:]
    static func image(_ key: String) -> NSImage? {
        if let hit = cache[key] { return hit }
        guard let g = named(key) else { return nil }
        let img = NSImage(size: NSSize(width: g.cellW, height: g.cellH))
        for b64 in [g.png1x, g.png2x] {
            guard let data = Data(base64Encoded: b64), let rep = NSBitmapImageRep(data: data) else { return nil }
            rep.size = img.size
            img.addRepresentation(rep)
        }
        img.isTemplate = true
        cache[key] = img
        return img
    }
}
